    *returnSize = n;
    int* dist = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) dist[i] = 1000000000;
    dist[start] = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < edgesSize; j++) {
            int u = edges[j][0], v = edges[j][1], w = edges[j][2];
            if (dist[u] != 1000000000 && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }
    for (int i = 0; i < n; i++) if (dist[i] == 1000000000) dist[i] = -1;
    return dist;
}

